/// Versioned, host-local resource envelope for reconstructing one exact
/// speculative JMT lineage.
///
/// These limits are availability policy, not consensus validity. Reaching any
/// of them must therefore surface as `HostResourceUnavailable`; it must never
/// become a durable invalid-payload result. This profile is fixed for the
/// schema-v10/application-v0 host contract. Changing it requires an explicit
/// host-profile/schema revision so restart cannot silently apply a different
/// hidden envelope to already-sealed work.
const NATIVE_SPECULATIVE_AUTH_RESOURCE_PROFILE_VERSION_V0: u16 = 0;
const MAX_NATIVE_SPECULATIVE_AUTH_NODE_FACTS_V0: u64 = 4 * 1024 * 1024;
const MAX_NATIVE_SPECULATIVE_AUTH_VALUE_FACTS_V0: u64 = 1024 * 1024;
const MAX_NATIVE_SPECULATIVE_AUTH_PREIMAGE_FACTS_V0: u64 = 1024 * 1024;
const MAX_NATIVE_SPECULATIVE_AUTH_LEAF_FACTS_V0: u64 = 1024 * 1024;
const MAX_NATIVE_SPECULATIVE_AUTH_INDEXED_BYTES_V0: u64 = 512 * 1024 * 1024;
const MAX_NATIVE_SPECULATIVE_AUTH_TOTAL_WORK_UNITS_V0: u64 = 16 * 1024 * 1024;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct NativeSpeculativeAuthResourceProfileV0 {
    version: u16,
    limits: SpeculativeAuthPathLimitsV0,
}

impl NativeSpeculativeAuthResourceProfileV0 {
    const CURRENT: Self = Self {
        version: NATIVE_SPECULATIVE_AUTH_RESOURCE_PROFILE_VERSION_V0,
        limits: SpeculativeAuthPathLimitsV0::new_v0(
            MAX_NATIVE_SPECULATIVE_AUTH_NODE_FACTS_V0,
            MAX_NATIVE_SPECULATIVE_AUTH_VALUE_FACTS_V0,
            MAX_NATIVE_SPECULATIVE_AUTH_PREIMAGE_FACTS_V0,
            MAX_NATIVE_SPECULATIVE_AUTH_LEAF_FACTS_V0,
            MAX_NATIVE_SPECULATIVE_AUTH_INDEXED_BYTES_V0,
            MAX_NATIVE_SPECULATIVE_AUTH_TOTAL_WORK_UNITS_V0,
        ),
    };
}

/// Store-private construction permit consumed only after an exact schema-v9
/// seal has committed or been confirmed byte-exact. It prevents a prepared
/// Valid owner from releasing live commitments before durable persistence.
pub(super) struct NativeValidationValidSealPermitV0(());

impl NativeValidationValidSealPermitV0 {
    fn new_v0() -> Self {
        Self(())
    }
}

/// Store-private permit proving that a route-stable speculative-overlay
/// request binding was derived from one deeply authenticated durable job row.
/// No sibling module can mint it from detached headers or configuration
/// digests.
pub(super) struct NativeSpeculativeOverlayBindingPermitV0(());

impl NativeSpeculativeOverlayBindingPermitV0 {
    fn new_v0() -> Self {
        Self(())
    }
}

