fn authenticated_genesis_h1_obligation_accounting_checksum_v0(
    accounting: NativeValidationJournalAccountingV0,
) -> [u8; 32] {
    hash_domain(
        "trnm.consensus-app.authenticated-genesis-h1-obligation-accounting.v0",
        &[
            &accounting.job_count.to_be_bytes(),
            &accounting.request_bytes.to_be_bytes(),
            &accounting.artifact_bytes.to_be_bytes(),
            &accounting.outbox_count.to_be_bytes(),
            &accounting.outbox_bytes.to_be_bytes(),
        ],
    )
}

fn authenticated_genesis_h1_obligation_takeover_cut_checksum_v0(
    cut: &NativeAuthenticatedGenesisH1ObligationTakeoverCutV0,
) -> [u8; 32] {
    let source = [match cut.source {
        crate::NativeAuthenticatedGenesisH1ObligationTakeoverSourceV0::Absent => 0,
        crate::NativeAuthenticatedGenesisH1ObligationTakeoverSourceV0::Reserved => 1,
        crate::NativeAuthenticatedGenesisH1ObligationTakeoverSourceV0::CallbackPending => 2,
        crate::NativeAuthenticatedGenesisH1ObligationTakeoverSourceV0::Delivered => 3,
    }];
    let immutable_presence = [u8::from(cut.immutable_checksum.is_some())];
    let immutable_checksum = cut.immutable_checksum.unwrap_or([0; 32]);
    let row_presence = [u8::from(cut.job_row_checksum.is_some())];
    let job_row_checksum = cut.job_row_checksum.unwrap_or([0; 32]);
    let artifact_presence = [u8::from(cut.artifact_checksum.is_some())];
    let artifact_checksum = cut.artifact_checksum.unwrap_or([0; 32]);
    let outbox_presence = [u8::from(cut.outbox_checksum.is_some())];
    let outbox_checksum = cut.outbox_checksum.unwrap_or([0; 32]);
    let overlay_presence = [u8::from(cut.overlay_checksum.is_some())];
    let overlay_checksum = cut.overlay_checksum.unwrap_or([0; 32]);
    hash_domain(
        "trnm.consensus-app.authenticated-genesis-h1-obligation-takeover-cut.v0",
        &[
            &source,
            cut.validation_id.block_id().as_bytes(),
            &cut.validation_id.view().get().to_be_bytes(),
            &cut.validation_id.generation().to_be_bytes(),
            &cut.request_fingerprint,
            &immutable_presence,
            &immutable_checksum,
            &row_presence,
            &job_row_checksum,
            &artifact_presence,
            &artifact_checksum,
            &outbox_presence,
            &outbox_checksum,
            &overlay_presence,
            &overlay_checksum,
            &cut.accounting_checksum,
            &cut.recovery_closure_checksum,
            &cut.application_host_config_ref,
            &cut.carrier_binding_ref,
            &cut.commissioning_row_checksum,
        ],
    )
}

impl NativeAuthenticatedGenesisH1StableApplicationCutV0 {
    pub(crate) fn same_exact_acked_cut_v0(&self, other: &Self) -> bool {
        self.validation_id == other.validation_id
            && self.valid_result_checksum == other.valid_result_checksum
            && self.delivered_job_row_checksum == other.delivered_job_row_checksum
            && self.acked_job_row_checksum == other.acked_job_row_checksum
            && self.outbox_checksum == other.outbox_checksum
            && self.artifact_checksum == other.artifact_checksum
            && self.overlay_checksum == other.overlay_checksum
            && self.application_host_config_ref == other.application_host_config_ref
            && self.carrier_binding_ref == other.carrier_binding_ref
            && self.commissioning_row_checksum == other.commissioning_row_checksum
            && self.completion_carrier_checksum == other.completion_carrier_checksum
    }
}

impl ReconciledNativeApplicationValidCompletionV0 {
    pub(crate) fn same_exact_acked_cut_v0(&self, other: &Self) -> bool {
        self.route == other.route
            && self.validation_id == other.validation_id
            && self.safety_revision == other.safety_revision
            && self.safety_state_record_checksum == other.safety_state_record_checksum
            && self.valid_result_checksum == other.valid_result_checksum
            && self.post_ack_action == other.post_ack_action
            && self.accepted_envelope_checksum == other.accepted_envelope_checksum
            && self.acked_job_row_checksum == other.acked_job_row_checksum
    }
}

/// Fixed-snapshot, authority-free stable-cut facts for the h1 anchored
/// successor protocol. The caller supplies the independently authenticated
/// Safety state and (for rev2/rev4) current native-Valid transition.
#[derive(Debug, PartialEq, Eq)]
pub(crate) struct ReconciledNativeApplicationStateSyncAnchorSuccessorsV0 {
    pub(crate) phase: StateSyncAnchorSuccessorPhaseV0,
    pub(crate) matched_acked_jobs: u64,
    pub(crate) current_transition_exact: bool,
    current_safety_state_record_checksum: Option<[u8; 32]>,
    current_safety_chain_checksum: Option<[u8; 32]>,
    historical_h2_transition: Option<NativeValidTransitionV0>,
    historical_h2_accepted_core_payload_checksum: Option<[u8; 32]>,
}

impl ReconciledNativeApplicationStateSyncAnchorSuccessorsV0 {
    pub(crate) fn historical_current_safety_head_matches_v0(
        &self,
        state_record_checksum: [u8; 32],
        chain_checksum: [u8; 32],
    ) -> bool {
        self.phase == StateSyncAnchorSuccessorPhaseV0::H3Valid
            && self.current_safety_state_record_checksum == Some(state_record_checksum)
            && self.current_safety_chain_checksum == Some(chain_checksum)
    }

    pub(crate) fn historical_h2_transition_v0(&self) -> Option<&NativeValidTransitionV0> {
        self.historical_h2_transition.as_ref()
    }

    pub(crate) fn historical_h2_accepted_envelope_matches_v0(
        &self,
        reconstructed_state_record_checksum: [u8; 32],
    ) -> bool {
        let (Some(transition), Some(accepted)) = (
            self.historical_h2_transition.as_ref(),
            self.historical_h2_accepted_core_payload_checksum,
        ) else {
            return false;
        };
        transition.completion_revision() == 2
            && transition.post_ack_action_code() == NativeValidPostAckActionV0::None.code()
            && native_validation_valid_accepted_envelope_checksum_v0(
                transition.route(),
                transition.validation_id(),
                transition.completion_revision(),
                reconstructed_state_record_checksum,
                NativeValidPostAckActionV0::None,
                transition.valid_result_checksum(),
                transition.callback_payload_checksum(),
                transition.idempotency_key(),
            ) == accepted
    }
}

impl AuditedNativeValidV0 {
    const fn key_v0(self) -> (PayloadValidationRouteV0, ValidationId) {
        (self.route, self.validation_id)
    }
}

fn audited_native_valid_completion_lifecycle_matches_v0(
    audited: AuditedNativeValidV0,
    first_recorded_revision: u64,
) -> bool {
    matches!(
        audited.state,
        NativeValidationJobStateV0::Delivered
            | NativeValidationJobStateV0::Acked
            | NativeValidationJobStateV0::Applied
    ) && audited.accepted_core_revision == Some(first_recorded_revision)
        && audited.accepted_core_payload_checksum.is_some()
}

fn audited_native_valid_obligation_lifecycle_matches_v0(
    audited: AuditedNativeValidV0,
    safety_revision: u64,
) -> bool {
    match audited.state {
        NativeValidationJobStateV0::CallbackPending => {
            audited.accepted_core_revision.is_none()
                && audited.accepted_core_payload_checksum.is_none()
        }
        NativeValidationJobStateV0::Delivered => {
            safety_revision.checked_add(1).is_some_and(|revision| {
                audited.accepted_core_revision == Some(revision)
                    && audited.accepted_core_payload_checksum.is_some()
            })
        }
        _ => false,
    }
}

