/// Owner-preserving rejection from the dual application-authority install
/// boundary.
///
/// Both unique Core capabilities are returned together. No error path may
/// leave one private store slot populated while the other remains empty.
#[must_use = "a rejected dual authority install retains both unique Core owners"]
pub(crate) struct NativeCoreApplicationAuthoritiesInstallRejectionV0 {
    cause: NativeCoreApplicationAuthoritiesInstallFailureV0,
    seal: Box<CoreIssuedApplicationSealAuthorityV0>,
    finalization: Box<CoreIssuedApplicationFinalizationApplyAuthorityV0>,
}

impl fmt::Debug for NativeCoreApplicationAuthoritiesInstallRejectionV0 {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter
            .debug_struct("NativeCoreApplicationAuthoritiesInstallRejectionV0")
            .field("cause", &self.cause)
            .finish_non_exhaustive()
    }
}

impl NativeCoreApplicationAuthoritiesInstallRejectionV0 {
    fn new_v0(
        cause: NativeCoreApplicationAuthoritiesInstallFailureV0,
        seal: CoreIssuedApplicationSealAuthorityV0,
        finalization: CoreIssuedApplicationFinalizationApplyAuthorityV0,
    ) -> Self {
        Self {
            cause,
            seal: Box::new(seal),
            finalization: Box::new(finalization),
        }
    }

    pub(crate) const fn cause(&self) -> NativeCoreApplicationAuthoritiesInstallFailureV0 {
        self.cause
    }

    pub(crate) fn into_authorities_v0(
        self,
    ) -> (
        CoreIssuedApplicationSealAuthorityV0,
        CoreIssuedApplicationFinalizationApplyAuthorityV0,
    ) {
        (*self.seal, *self.finalization)
    }
}

/// Owner-preserving rejection from the ApplicationStore apply boundary.
///
/// No failure reconstructs a permit from comparison data. The sole live
/// permit is returned unchanged so the trusted host may retry it against its
/// issuing Core or halt without losing the queue-front owner.
#[must_use = "a rejected finalization apply retains the sole Core-issued permit"]
pub(super) struct NativeApplicationFinalizationApplyRejectionV0 {
    cause: NativeApplicationFinalizationApplyFailureCauseV0,
    permit: Box<CoreIssuedApplicationFinalizationPermitV0>,
}

impl fmt::Debug for NativeApplicationFinalizationApplyRejectionV0 {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter
            .debug_struct("NativeApplicationFinalizationApplyRejectionV0")
            .field("cause", &self.cause)
            .field("permit", &self.permit)
            .finish()
    }
}

impl NativeApplicationFinalizationApplyRejectionV0 {
    fn new_v0(
        cause: NativeApplicationFinalizationApplyFailureCauseV0,
        permit: CoreIssuedApplicationFinalizationPermitV0,
    ) -> Self {
        Self {
            cause,
            permit: Box::new(permit),
        }
    }

    #[cfg_attr(not(test), allow(dead_code))]
    pub(super) const fn cause(&self) -> NativeApplicationFinalizationApplyFailureCauseV0 {
        self.cause
    }

    #[cfg_attr(not(test), allow(dead_code))]
    pub(super) fn into_permit(self) -> CoreIssuedApplicationFinalizationPermitV0 {
        *self.permit
    }
}

