fn native_authenticated_genesis_commissioning_binding_v0(
    carrier: AuthenticatedGenesisApplicationParentV0,
    application_host_config_ref: [u8; 32],
    descriptor_ref: [u8; 32],
    projection_profile_ref: [u8; 32],
    safety: NativeAuthenticatedGenesisSafetyBindingFactsV0,
) -> Result<NativeAuthenticatedGenesisCommissioningBindingV0> {
    ensure!(
        safety.revision == 0
            && descriptor_ref != [0; 32]
            && projection_profile_ref != [0; 32]
            && carrier.descriptor_ref() == descriptor_ref
            && carrier.projection_profile_ref() == projection_profile_ref,
        "authenticated-genesis commissioning inputs differ from the independently derived carrier"
    );
    Ok(NativeAuthenticatedGenesisCommissioningBindingV0 {
        carrier_binding_ref: carrier.binding_ref_v0(),
        application_host_config_ref,
        descriptor_ref,
        projection_profile_ref,
        safety_journal_id: safety.journal_id,
        safety_verifier_profile_ref: safety.verifier_profile_ref,
        safety_core_config_ref: safety.core_config_ref,
        safety_revision: safety.revision,
        safety_state_record_checksum: safety.state_record_checksum,
        safety_transition_context_checksum: safety.transition_context_checksum,
        safety_chain_checksum: safety.chain_checksum,
        safety_head_checksum: safety.head_checksum,
        committed_head_row_checksum: native_authenticated_genesis_application_head_row_checksum_v0(
            carrier,
        ),
    })
}

