    #[cfg_attr(not(test), allow(dead_code))]
    fn begin_authenticated_runtime_read_snapshot_v0(
        &self,
        expected_parent: Option<AuthenticatedRuntimeExpectedParentV0>,
    ) -> std::result::Result<AuthenticatedRuntimeReadSnapshotV0, AuthenticatedRuntimeReadFailureV0>
    {
        let _maintenance = match self.maintenance_gate.try_lock() {
            Ok(maintenance) => maintenance,
            Err(TryLockError::WouldBlock) => {
                return Err(AuthenticatedRuntimeReadFailureV0::HostResourceUnavailable {
                    stage: AuthenticatedRuntimeReadStageV0::BeginSnapshot,
                    sqlite: None,
                    reason: "application store maintenance is busy",
                });
            }
            Err(TryLockError::Poisoned(_)) => {
                return Err(AuthenticatedRuntimeReadFailureV0::HostInvariant {
                    stage: AuthenticatedRuntimeReadStageV0::BeginSnapshot,
                    sqlite: None,
                    reason: "application store maintenance gate is poisoned",
                });
            }
        };
        let connection = self.connect_authenticated_runtime_read_v0()?;
        connection
            .execute_batch("BEGIN DEFERRED")
            .map_err(|error| {
                classify_sqlite_authenticated_read_failure_v0(
                    AuthenticatedRuntimeReadStageV0::BeginSnapshot,
                    &error,
                )
            })?;

        let validated = (|| {
            if read_native_committed_head_v0(&connection)
                .map_err(|error| {
                    classify_authenticated_read_anyhow_v0(
                        AuthenticatedRuntimeReadStageV0::ValidateBindings,
                        &error,
                        "native committed head is malformed",
                    )
                })?
                .is_some_and(|head| {
                    matches!(
                        head.provenance,
                        NativeCommittedHeadProvenanceV0::AuthenticatedGenesisApplication(_)
                    )
                })
            {
                return Err(AuthenticatedRuntimeReadFailureV0::SourceMismatch {
                    stage: AuthenticatedRuntimeReadStageV0::ValidateBindings,
                    reason: "authenticated-genesis application requires its dedicated inert bootstrap owner",
                });
            }
            let (committed_height, committed_root) =
                self.validate_authenticated_runtime_snapshot_head_v0(&connection)?;
            let Some(expected_parent) = expected_parent else {
                return Ok((committed_height, committed_root, None));
            };
            match expected_parent.provenance {
                #[cfg(test)]
                AuthenticatedRuntimeExpectedParentProvenanceV0::TestCoordinates => {
                    if (committed_height, committed_root)
                        != (expected_parent.height, expected_parent.root_hash)
                    {
                        return Err(AuthenticatedRuntimeReadFailureV0::SourceMismatch {
                            stage: AuthenticatedRuntimeReadStageV0::ValidateBindings,
                            reason: "test parent coordinates differ from the committed head",
                        });
                    }
                    return Ok((committed_height, committed_root, None));
                }
                AuthenticatedRuntimeExpectedParentProvenanceV0::Finalized => {
                    let expected_block_id = expected_parent.block_id.ok_or(
                        AuthenticatedRuntimeReadFailureV0::AuthenticatedStateInvariant {
                            stage: AuthenticatedRuntimeReadStageV0::ValidateBindings,
                            sqlite: None,
                            reason: "Core-finalized parent lacks an exact BlockId",
                        },
                    )?;
                    if (committed_height, committed_root)
                        != (expected_parent.height, expected_parent.root_hash)
                    {
                        return Err(AuthenticatedRuntimeReadFailureV0::SourceMismatch {
                            stage: AuthenticatedRuntimeReadStageV0::ValidateBindings,
                            reason: "Core-finalized parent differs from the committed head",
                        });
                    }
                    let committed_anchor = read_committed_native_anchor_v0(&connection)
                        .map_err(|error| {
                            classify_authenticated_read_anyhow_v0(
                                AuthenticatedRuntimeReadStageV0::ValidateBindings,
                                &error,
                                "committed native BlockId anchor is malformed",
                            )
                        })?
                        .ok_or(
                            AuthenticatedRuntimeReadFailureV0::AuthenticatedStateInvariant {
                                stage: AuthenticatedRuntimeReadStageV0::ValidateBindings,
                                sqlite: None,
                                reason: "committed native BlockId anchor is absent",
                            },
                        )?;
                    if committed_anchor.height != committed_height
                        || committed_anchor.state_root != committed_root
                        || committed_anchor.block_id != expected_block_id
                    {
                        return Err(
                            AuthenticatedRuntimeReadFailureV0::AuthenticatedStateInvariant {
                                stage: AuthenticatedRuntimeReadStageV0::ValidateBindings,
                                sqlite: None,
                                reason:
                                    "Core-finalized parent differs from committed native anchor",
                            },
                        );
                    }
                    return Ok((committed_height, committed_root, None));
                }
                AuthenticatedRuntimeExpectedParentProvenanceV0::Speculative(expected_overlay) => {
                    let target_block_id = expected_parent.block_id.ok_or(
                        AuthenticatedRuntimeReadFailureV0::AuthenticatedStateInvariant {
                            stage: AuthenticatedRuntimeReadStageV0::ValidateBindings,
                            sqlite: None,
                            reason: "Core-speculative parent lacks an exact BlockId",
                        },
                    )?;
                    if expected_overlay.block_id() != target_block_id {
                        return Err(
                            AuthenticatedRuntimeReadFailureV0::AuthenticatedStateInvariant {
                                stage: AuthenticatedRuntimeReadStageV0::ValidateBindings,
                                sqlite: None,
                                reason: "Core speculative overlay names a different parent",
                            },
                        );
                    }
                    let loaded =
                        load_native_speculative_overlay_v0(
                            &connection,
                            target_block_id,
                            NativeValidationReservationStageV0::ReadExisting,
                        )
                        .map_err(native_speculative_lineage_runtime_failure_v0)?
                        .ok_or(AuthenticatedRuntimeReadFailureV0::SourceMismatch {
                            stage: AuthenticatedRuntimeReadStageV0::ValidateBindings,
                            reason:
                                "the exact Core-issued speculative parent overlay is unavailable",
                        })?;
                    if loaded.core_ref_v0() != expected_overlay {
                        return Err(
                            AuthenticatedRuntimeReadFailureV0::AuthenticatedStateInvariant {
                                stage: AuthenticatedRuntimeReadStageV0::ValidateBindings,
                                sqlite: None,
                                reason: "persisted overlay differs from Core speculative parent",
                            },
                        );
                    }
                }
            }
            let target_block_id = expected_parent
                .block_id
                .expect("closed speculative provenance checked the exact parent BlockId");
            if load_native_speculative_overlay_v0(
                &connection,
                target_block_id,
                NativeValidationReservationStageV0::ReadExisting,
            )
            .map_err(native_speculative_lineage_runtime_failure_v0)?
            .is_none()
            {
                return Err(AuthenticatedRuntimeReadFailureV0::SourceMismatch {
                    stage: AuthenticatedRuntimeReadStageV0::ValidateBindings,
                    reason: "the exact Core-issued speculative parent overlay is unavailable",
                });
            }
            let lineage = load_native_speculative_lineage_v0(
                &connection,
                self,
                target_block_id,
                committed_height,
                committed_root,
                NativeValidationReservationStageV0::ReadExisting,
            )
            .map_err(native_speculative_lineage_runtime_failure_v0)?;
            if lineage.block_id != target_block_id
                || lineage.height != expected_parent.height
                || lineage.root_hash != expected_parent.root_hash
                || lineage.overlay_checksum
                    != match expected_parent.provenance {
                        AuthenticatedRuntimeExpectedParentProvenanceV0::Speculative(overlay) => {
                            overlay.overlay_checksum()
                        }
                        #[cfg(test)]
                        AuthenticatedRuntimeExpectedParentProvenanceV0::TestCoordinates
                        | AuthenticatedRuntimeExpectedParentProvenanceV0::Finalized => {
                            unreachable!("only speculative provenance reaches lineage validation")
                        }
                        #[cfg(not(test))]
                        AuthenticatedRuntimeExpectedParentProvenanceV0::Finalized => {
                            unreachable!("only speculative provenance reaches lineage validation")
                        }
                    }
            {
                return Err(
                    AuthenticatedRuntimeReadFailureV0::AuthenticatedStateInvariant {
                        stage: AuthenticatedRuntimeReadStageV0::ValidateBindings,
                        sqlite: None,
                        reason: "speculative overlay lineage differs from the exact Core parent",
                    },
                );
            }
            Ok((lineage.height, lineage.root_hash, Some(lineage)))
        })();
        match validated {
            Ok((height, root_hash, speculative)) => {
                self.active_snapshot_pins.fetch_add(1, Ordering::AcqRel);
                Ok(AuthenticatedRuntimeReadSnapshotV0 {
                    source: Some(connection),
                    height,
                    root_hash,
                    speculative,
                    active_snapshot_pins: Arc::clone(&self.active_snapshot_pins),
                    #[cfg(test)]
                    fail_finish_for_test_v0: false,
                })
            }
            Err(error) => {
                let rollback = connection.execute_batch("ROLLBACK").map_err(|rollback| {
                    classify_sqlite_authenticated_read_failure_v0(
                        AuthenticatedRuntimeReadStageV0::EndSnapshot,
                        &rollback,
                    )
                });
                merge_authenticated_runtime_read_and_rollback_v0(Err(error), rollback)
            }
        }
    }

