    #[test]
    fn application_finalization_authority_is_single_install_shared_and_not_reopened_v0() {
        let mut fixture = durable_valid_seal_test_fixture_v0(PayloadValidationRouteV0::Proposal);
        let core = fixture.take_core_v0();
        let store = fixture.store_v0().clone();
        let shared = store.clone();

        let issuing_core = core.clone();
        let authority = issuing_core
            .issue_application_finalization_apply_authority_v0()
            .expect("issue one application-finalization authority");
        store
            .install_core_application_finalization_apply_authority_v0(authority)
            .expect("install one application-finalization authority");
        assert!(shared
            .core_application_finalization_apply_authority
            .lock()
            .expect("inspect shared authority slot")
            .is_some());

        let foreign_core = core.clone();
        let second = foreign_core
            .issue_application_finalization_apply_authority_v0()
            .expect("issue an independent foreign authority");
        assert!(shared
            .install_core_application_finalization_apply_authority_v0(second)
            .is_err());

        let rebound = store.with_database_path(store.database_path.clone());
        assert!(rebound
            .core_application_finalization_apply_authority
            .lock()
            .expect("inspect rebound authority slot")
            .is_none());
        let reopened = ApplicationStore::open(
            &store.status_path,
            &store.chain_id,
            &store.signer_policy_hash_hex,
        )
        .expect("reopen the same application namespace");
        assert!(reopened
            .core_application_finalization_apply_authority
            .lock()
            .expect("inspect reopened authority slot")
            .is_none());
    }

    #[test]
    fn indexed_speculative_resource_failures_are_local_unavailability_not_payload_capacity_v0() {
        for error in [
            super::SpeculativeAuthPathErrorV0::ResourceLimit {
                resource:
                    crate::auth_tree::durable_plan::SpeculativeAuthPathResourceV0::IndexedBytes,
                current: 7,
                added: 2,
                maximum: 8,
            },
            super::SpeculativeAuthPathErrorV0::HostAllocation {
                stage: "reserve indexed speculative fact",
                detail: "injected allocation refusal".to_owned(),
            },
        ] {
            assert!(matches!(
                super::classify_native_speculative_auth_path_error_v0(
                    NativeValidationReservationStageV0::ReadExisting,
                    error,
                ),
                NativeValidationReservationFailureCauseV0::HostResourceUnavailable {
                    stage: NativeValidationReservationStageV0::ReadExisting,
                    sqlite: None,
                }
            ));
        }

        assert!(matches!(
            super::classify_native_speculative_auth_path_error_v0(
                NativeValidationReservationStageV0::ReadExisting,
                super::SpeculativeAuthPathErrorV0::Revalidation(anyhow::anyhow!(
                    "injected physical-plan mismatch"
                )),
            ),
            NativeValidationReservationFailureCauseV0::Invariant {
                stage: NativeValidationReservationStageV0::ReadExisting,
                kind: NativeValidationReservationInvariantV0::ChecksumMismatch,
                sqlite: None,
            }
        ));

        let typed_startup = super::native_application_startup_reservation_error_v0(
            "injected startup resource refusal",
            NativeValidationReservationFailureCauseV0::HostResourceUnavailable {
                stage: NativeValidationReservationStageV0::ReadExisting,
                sqlite: None,
            },
        );
        assert_eq!(
            super::native_application_startup_audit_failure_v0(&typed_startup),
            NativeApplicationFinalizationApplyFailureCauseV0::HostResourceUnavailable,
            "typed deep-audit resource failure must not collapse into persisted corruption",
        );
    }

    #[test]
    fn native_valid_startup_open_and_commit_readback_keep_resource_taxonomy_v0() {
        let sqlite_oom = anyhow::Error::new(rusqlite::Error::SqliteFailure(
            rusqlite::ffi::Error::new(rusqlite::ffi::SQLITE_NOMEM),
            None,
        ));
        assert_eq!(
            super::native_application_startup_open_failure_v0(&sqlite_oom),
            NativeApplicationFinalizationApplyFailureCauseV0::HostResourceUnavailable,
            "read-only startup open must preserve SQLite OOM",
        );
        let sqlite_busy = anyhow::Error::new(rusqlite::Error::SqliteFailure(
            rusqlite::ffi::Error::new(rusqlite::ffi::SQLITE_BUSY),
            None,
        ));
        assert_eq!(
            super::native_application_startup_open_failure_v0(&sqlite_busy),
            NativeApplicationFinalizationApplyFailureCauseV0::DatabaseUnavailable,
        );
        assert_eq!(
            super::native_application_startup_open_failure_v0(&anyhow::anyhow!(
                "injected non-SQLite open failure"
            )),
            NativeApplicationFinalizationApplyFailureCauseV0::DatabaseUnavailable,
        );

        use super::{
            NativeValidCompletionCommitReadbackCutV0 as Cut,
            NativeValidCompletionCommitReadbackDecisionV0 as Decision,
        };
        assert_eq!(
            super::native_valid_completion_commit_readback_decision_v0(Ok(Cut::ExactAcked)),
            Decision::Committed,
        );
        assert_eq!(
            super::native_valid_completion_commit_readback_decision_v0(Ok(Cut::ExactDelivered)),
            Decision::RolledBack,
        );
        assert_eq!(
            super::native_valid_completion_commit_readback_decision_v0(Ok(Cut::Contradictory)),
            Decision::PersistedStateMismatch,
        );
        for cause in [
            NativeApplicationFinalizationApplyFailureCauseV0::DatabaseUnavailable,
            NativeApplicationFinalizationApplyFailureCauseV0::HostResourceUnavailable,
            NativeApplicationFinalizationApplyFailureCauseV0::CommitUncertain,
        ] {
            assert_eq!(
                super::native_valid_completion_commit_readback_decision_v0(Err(cause)),
                Decision::CommitUncertain,
                "unavailable fresh readback must retain an uncertain commit disposition",
            );
            assert_eq!(
                super::native_valid_completion_commit_readback_failure_v0(cause),
                NativeApplicationFinalizationApplyFailureCauseV0::CommitUncertain,
                "stable D-to-K must reuse the same uncertain-readback taxonomy",
            );
        }
        for cause in [
            NativeApplicationFinalizationApplyFailureCauseV0::NamespaceMismatch,
            NativeApplicationFinalizationApplyFailureCauseV0::PersistedStateMismatch,
            NativeApplicationFinalizationApplyFailureCauseV0::Injected,
        ] {
            assert_eq!(
                super::native_valid_completion_commit_readback_decision_v0(Err(cause)),
                Decision::PersistedStateMismatch,
                "only typed local unavailability may downgrade a failed readback to uncertain",
            );
            assert_eq!(
                super::native_valid_completion_commit_readback_failure_v0(cause),
                NativeApplicationFinalizationApplyFailureCauseV0::PersistedStateMismatch,
                "stable D-to-K must preserve deterministic readback contradictions",
            );
        }
    }

    #[test]
    fn durable_parent_pointer_must_match_the_exact_indexed_lineage_edge_v0() {
        assert!(
            super::durable_native_validation_parent_pointer_matches_lineage_edge_v0(
                super::DurableNativeValidationParentPointerV0::Finalized,
                None,
                None,
            )
        );

        let parent = BlockIdOverlayRefV0::new(
            BlockId::new([0x41; 32]),
            BlockId::new([0x31; 32]),
            [0x51; 32],
        );
        let foreign_same_edge_coordinates = BlockIdOverlayRefV0::new(
            BlockId::new([0x42; 32]),
            parent.parent_block_id(),
            parent.overlay_checksum(),
        );
        let foreign_parent_lineage = BlockIdOverlayRefV0::new(
            parent.block_id(),
            BlockId::new([0x32; 32]),
            parent.overlay_checksum(),
        );
        let persisted_edge = Some((parent.block_id(), parent.overlay_checksum()));
        assert!(
            super::durable_native_validation_parent_pointer_matches_lineage_edge_v0(
                super::DurableNativeValidationParentPointerV0::Speculative(parent),
                persisted_edge,
                Some(parent),
            )
        );
        assert!(
            !super::durable_native_validation_parent_pointer_matches_lineage_edge_v0(
                super::DurableNativeValidationParentPointerV0::Speculative(parent),
                persisted_edge,
                Some(foreign_same_edge_coordinates),
            )
        );
        assert!(
            !super::durable_native_validation_parent_pointer_matches_lineage_edge_v0(
                super::DurableNativeValidationParentPointerV0::Speculative(parent),
                persisted_edge,
                Some(foreign_parent_lineage),
            )
        );
    }

    /// Test-only lifecycle fixture for an executable speculative parent.
    ///
    /// The production selector intentionally rejects a merely sealed Valid-P
    /// source. This helper advances that already deeply verified row to the
    /// narrow durable Acked shape without minting any live Core/Safety
    /// capability. It uses the canonical accepted-envelope and job-row
    /// checksum functions, removes the exact callback outbox, and updates the
    /// accounting singleton in the same transaction.
    pub(super) fn promote_valid_callback_pending_fixture_to_acked_v0(
        store: &ApplicationStore,
        live: &crate::NativeValidationValidCallbackV0,
    ) {
        let mut connection = store.connect().expect("open Valid-P lifecycle fixture");
        let transaction = connection
            .transaction_with_behavior(rusqlite::TransactionBehavior::Immediate)
            .expect("begin test-only Valid-P to Acked transition");
        let accounting = super::read_mixed_native_validation_journal_accounting_v11_v0(
            &transaction,
            NativeValidationReservationStageV0::ReadExisting,
        )
        .expect("audit Valid-P lifecycle fixture before promotion");
        let existing = super::load_native_validation_job_v0(&transaction, live.validation_id())
            .expect("load Valid-P lifecycle fixture")
            .expect("Valid-P lifecycle fixture exists");
        let job = super::durable_native_validation_job_from_existing_v0(existing, store)
            .expect("decode Valid-P lifecycle fixture");
        assert_eq!(job.state(), NativeValidationJobStateV0::CallbackPending);
        super::verify_native_validation_valid_job_overlay_v10_v0(
            &transaction,
            store,
            &job,
            NativeValidationReservationStageV0::ReadExisting,
            true,
        )
        .expect("deep-verify Valid-P lifecycle fixture before promotion");

        let commitments = live.validated_commitments();
        let artifact_ref = live.artifact_ref();
        let overlay = artifact_ref.overlay();
        let logical_block_size = commitments.logical_block_size().to_be_bytes();
        let transaction_count = commitments.transaction_count().to_be_bytes();
        let evidence_count = commitments.evidence_count().to_be_bytes();
        let valid_result_checksum = super::hash_domain(
            trnm_consensus_core::NATIVE_VALID_RESULT_CHECKSUM_DOMAIN_V0,
            &[
                commitments.block_id().as_bytes(),
                &logical_block_size,
                &transaction_count,
                &evidence_count,
                overlay.block_id().as_bytes(),
                overlay.parent_block_id().as_bytes(),
                &overlay.overlay_checksum(),
                &artifact_ref.source_artifact_checksum(),
            ],
        );
        let accepted_core_revision = live
            .validation_id()
            .generation()
            .checked_add(1)
            .expect("fixture Core revision remains in range");
        let accepted_core_revision_be = accepted_core_revision.to_be_bytes();
        let accepted_envelope_checksum =
            super::native_validation_valid_accepted_envelope_checksum_v0(
                live.route(),
                live.validation_id(),
                accepted_core_revision,
                [0xA5; 32],
                super::NativeValidPostAckActionV0::None,
                valid_result_checksum,
                live.callback_payload_checksum(),
                live.idempotency_key(),
            );
        let acked_row_checksum = super::native_validation_job_delivery_row_checksum_v0(
            &job.immutable_checksum,
            NativeValidationJobStateV0::Acked,
            job.result_kind,
            job.invalid_reason_code_be.as_deref(),
            job.artifact_codec.as_deref(),
            job.artifact_checksum.as_ref(),
            Some(accepted_core_revision_be.as_slice()),
            Some(&accepted_envelope_checksum),
            None,
        );
        let deleted = transaction
            .execute(
                "DELETE FROM validation_callback_outbox_v0
                 WHERE route=?1 AND block_id=?2 AND view_be=?3 AND generation_be=?4
                   AND delivery_attempt_be=zeroblob(8)",
                rusqlite::params![
                    super::native_validation_route_code_v0(live.route()),
                    live.validation_id().block_id().as_bytes().as_slice(),
                    live.validation_id().view().get().to_be_bytes().as_slice(),
                    live.validation_id().generation().to_be_bytes().as_slice(),
                ],
            )
            .expect("retire exact Valid callback outbox in test-only promotion");
        assert_eq!(deleted, 1);
        let updated = transaction
            .execute(
                "UPDATE validation_jobs_v0
                 SET state=4, accepted_core_revision_be=?1,
                     accepted_core_payload_checksum=?2, row_checksum=?3
                 WHERE route=?4 AND block_id=?5 AND view_be=?6 AND generation_be=?7
                   AND state=2 AND row_checksum=?8",
                rusqlite::params![
                    accepted_core_revision_be.as_slice(),
                    accepted_envelope_checksum.as_slice(),
                    acked_row_checksum.as_slice(),
                    super::native_validation_route_code_v0(live.route()),
                    live.validation_id().block_id().as_bytes().as_slice(),
                    live.validation_id().view().get().to_be_bytes().as_slice(),
                    live.validation_id().generation().to_be_bytes().as_slice(),
                    job.row_checksum.as_slice(),
                ],
            )
            .expect("advance exact Valid-P row to Acked in test-only promotion");
        assert_eq!(updated, 1);
        let outbox_count = accounting
            .outbox_count
            .checked_sub(1)
            .expect("Valid-P fixture owns one callback outbox");
        let outbox_bytes = accounting
            .outbox_bytes
            .checked_sub(super::DURABLE_VALID_CALLBACK_BYTES_V0 as u64)
            .expect("Valid-P fixture accounts one callback payload");
        let accounting_updated = transaction
            .execute(
                "UPDATE validation_journal_accounting_v0
                 SET outbox_count_be=?1, outbox_bytes_be=?2
                 WHERE singleton=1 AND outbox_count_be=?3 AND outbox_bytes_be=?4",
                rusqlite::params![
                    outbox_count.to_be_bytes().as_slice(),
                    outbox_bytes.to_be_bytes().as_slice(),
                    accounting.outbox_count.to_be_bytes().as_slice(),
                    accounting.outbox_bytes.to_be_bytes().as_slice(),
                ],
            )
            .expect("update exact Valid callback accounting in test-only promotion");
        assert_eq!(accounting_updated, 1);
        super::read_mixed_native_validation_journal_accounting_v11_v0(
            &transaction,
            NativeValidationReservationStageV0::ReadExisting,
        )
        .expect("audit checksum-valid Acked lifecycle fixture");
        transaction
            .commit()
            .expect("commit test-only Valid-P to Acked transition");
    }

    fn audited_valid_fixture_v0(
        store: &ApplicationStore,
        route: PayloadValidationRouteV0,
        validation_id: ValidationId,
    ) -> super::AuditedNativeValidV0 {
        let connection = store.connect_read().expect("open Valid lifecycle audit");
        connection
            .execute_batch("BEGIN DEFERRED")
            .expect("pin Valid lifecycle audit snapshot");
        let mut found = None;
        store
            .visit_native_validation_recovery_work_with_audited_valid_v0(
                &connection,
                |_| Ok(()),
                |audited| {
                    if audited.key_v0() == (route, validation_id) {
                        assert!(found.replace(audited).is_none());
                    }
                    Ok(())
                },
            )
            .expect("deep-audit Valid lifecycle fixture");
        connection
            .execute_batch("ROLLBACK")
            .expect("release Valid lifecycle audit snapshot");
        found.expect("Valid lifecycle fixture is present in the audited index")
    }

    #[test]
    fn audited_valid_lifecycle_rejects_completion_with_callback_pending_app_row_v0() {
        let mut fixture = durable_valid_seal_test_fixture_v0(PayloadValidationRouteV0::Proposal);
        let prepared = fixture.take_prepared_v0();
        let store = fixture.store_v0().clone();
        let live = match store
            .seal_durable_valid_and_enqueue_callback_v0(prepared)
            .expect("seal exact Valid-P fixture")
        {
            NativeValidationValidSealDecisionV0::CallbackPending(live) => live,
            NativeValidationValidSealDecisionV0::Existing(_) => {
                panic!("fresh Valid-P fixture unexpectedly existed")
            }
        };
        let route = live.route();
        let validation_id = live.validation_id();
        let mut core = fixture.take_core_v0();
        let accepted = (*live)
            .submit_to_core_v0(&mut core, &CoreRootSignatures)
            .expect("Core records the exact Valid completion");
        let completion = core
            .safety_state()
            .payload_validation_completions()
            .iter()
            .find(|completion| completion.key() == (route, validation_id))
            .expect("Core retains the exact Valid completion");
        assert_eq!(
            completion.first_recorded_revision(),
            accepted.completion_revision_v0()
        );
        let audited = audited_valid_fixture_v0(&store, route, validation_id);
        assert_eq!(audited.state, NativeValidationJobStateV0::CallbackPending);
        assert!(
            !super::audited_native_valid_completion_lifecycle_matches_v0(
                audited,
                completion.first_recorded_revision(),
            ),
            "C+P must never pass the Safety/Application lifecycle join"
        );
    }

    #[test]
    fn audited_valid_lifecycle_rejects_obligation_with_acked_app_row_v0() {
        let mut fixture = durable_valid_seal_test_fixture_v0(PayloadValidationRouteV0::Proposal);
        let prepared = fixture.take_prepared_v0();
        let store = fixture.store_v0().clone();
        let live = match store
            .seal_durable_valid_and_enqueue_callback_v0(prepared)
            .expect("seal exact Valid-P fixture")
        {
            NativeValidationValidSealDecisionV0::CallbackPending(live) => live,
            NativeValidationValidSealDecisionV0::Existing(_) => {
                panic!("fresh Valid-P fixture unexpectedly existed")
            }
        };
        let route = live.route();
        let validation_id = live.validation_id();
        promote_valid_callback_pending_fixture_to_acked_v0(&store, &live);
        let core = fixture.take_core_v0();
        assert!(core
            .safety_state()
            .payload_validation_obligations()
            .iter()
            .any(|obligation| { obligation.route() == route && obligation.id() == validation_id }));
        let audited = audited_valid_fixture_v0(&store, route, validation_id);
        assert_eq!(audited.state, NativeValidationJobStateV0::Acked);
        assert!(
            !super::audited_native_valid_obligation_lifecycle_matches_v0(
                audited,
                core.safety_state().revision(),
            ),
            "O+K must never pass the Safety/Application lifecycle join"
        );
    }

    #[test]
