    fn virgin_authenticated_genesis_projection_store_with_policy_and_shape_v0(
        label: &str,
        signer_policy_hash_hex: &str,
        shape: AuthenticatedGenesisProjectionFixtureV0,
    ) -> (
        PathBuf,
        ApplicationStore,
        crate::AppState,
        crate::auth_tree::InMemoryAuthTree,
        crate::auth_tree::PlannedAuthUpdate,
    ) {
        let unique = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .expect("system time after epoch")
            .as_nanos();
        let root = std::env::temp_dir().join(format!(
            "trnm-native-validation-reservation-{label}-{}-{unique}",
            std::process::id()
        ));
        fs::create_dir_all(&root).expect("create commissioning test directory");
        fs::set_permissions(&root, fs::Permissions::from_mode(0o700))
            .expect("protect commissioning test directory");
        let store = ApplicationStore::open(
            &root.join("app.status"),
            "reservation-test-chain",
            signer_policy_hash_hex,
        )
        .expect("construct commissioning test store");
        store
            .load_or_migrate()
            .expect("initialize commissioning test store");
        let lifecycle = crate::validator_lifecycle::ValidatorLifecycleStateV1::from_genesis(
            "reservation-test-chain".to_string(),
            crate::APP_VERSION,
            signer_policy_hash_hex.to_string(),
            crate::validator_lifecycle::ValidatorGovernanceV1 {
                schema: crate::validator_lifecycle::VALIDATOR_GOVERNANCE_SCHEMA_V1.to_string(),
                signer_id: "did:operator:app-v13-commissioning-test".to_string(),
                min_activation_delay_blocks: 2,
                unsafe_allow_single_validator_genesis: false,
            },
            [1_u8, 2, 3, 4]
                .into_iter()
                .map(|seed| crate::validator_lifecycle::ConsensusValidatorV1 {
                    public_key_hex: hex::encode([seed; 32]),
                    voting_power: 10,
                })
                .collect(),
        )
        .expect("construct commissioning validator lifecycle");
        let mut state = crate::AppState {
            height: 0,
            validator_lifecycle: Some(lifecycle.clone()),
            ..crate::AppState::default()
        };
        let mut writes = vec![crate::authenticated_lifecycle_write(0, &lifecycle)
            .expect("encode commissioning lifecycle write")];
        match shape {
            AuthenticatedGenesisProjectionFixtureV0::ExactInactive => {}
            AuthenticatedGenesisProjectionFixtureV0::Namespace8Manifest => {
                let manifest =
                    crate::poco_snapshot::PocoSnapshotManifestV0::from_entries(Height::new(0), &[])
                        .expect("construct empty but present namespace-8 manifest");
                writes.push(
                    crate::auth_tree::AuthWrite::put_poco_snapshot(
                        crate::poco_transition::PocoWritePermitV0::test_only(),
                        crate::poco_snapshot::poco_snapshot_manifest_key()
                            .expect("construct namespace-8 manifest key"),
                        manifest.encode(),
                    )
                    .expect("encode namespace-8 manifest write"),
                );
            }
            AuthenticatedGenesisProjectionFixtureV0::PocoAuthorityObject => {
                let authority = crate::PocoAuthorityConfigV0 {
                    schema: crate::POCO_AUTHORITY_CONFIG_SCHEMA_V0.to_string(),
                    genesis_hash_hex: hex::encode([0xa5; 32]),
                    protocol_profile_hash_hex: hex::encode([0xb6; 32]),
                };
                let object = crate::poco_authority_object(&authority);
                writes.push(
                    crate::authenticated_object_write(&object)
                        .expect("encode authenticated PoCO authority object"),
                );
                assert!(state
                    .objects
                    .insert(object.object_key_hex.clone(), object)
                    .is_none());
            }
        }
        let mut tree = crate::auth_tree::InMemoryAuthTree::default();
        let plan = tree
            .plan_put_value_set(0, writes)
            .expect("plan commissioning version-zero JMT");
        let commissioning_plan = plan.clone();
        let root_hash = tree
            .apply(plan)
            .expect("apply commissioning version-zero JMT");
        state.app_hash = root_hash.0;
        store
            .replace_empty_state_from_tree(&crate::AppState::default(), &state, &tree)
            .expect("install commissioning version-zero projection");
        (root, store, state, tree, commissioning_plan)
    }

