    fn production_authenticated_genesis_empty_h1_v0(
        core_config: &CoreConfig,
        genesis: GenesisQcV0,
    ) -> SignedProposalV0 {
        let set = core_config.validator_set();
        let parameters = core_config.consensus_parameters();
        let justify = QcReferenceV0::genesis_anchor(genesis);
        let proposer = leader_for(set, View::new(1));
        let application_payload =
            ApplicationPayloadV0::new(Vec::new()).expect("construct empty h1 payload");
        let receipts = ExecutionReceiptsV0::new(&application_payload, Vec::new())
            .expect("construct empty h1 receipts");
        let body =
            BlockBodyV0::new(application_payload, Vec::new()).expect("construct empty h1 body");
        let parent = core_config
            .authenticated_genesis_application_parent_v0()
            .expect("production fixture has authenticated parent");
        let header = BlockHeader::new(
            set.genesis_hash(),
            set.chain_id(),
            set.protocol_version(),
            set.epoch(),
            View::new(1),
            Height::new(1),
            BlockKind::Regular,
            parent.genesis_block_id(),
            proposer,
            set.id(),
            set.consensus_parameters_hash(),
            body.payload_root().expect("derive empty h1 payload root"),
            parent.state_root(),
            receipts
                .receipts_root()
                .expect("derive empty h1 receipts root"),
            body.evidence_root().expect("derive empty h1 evidence root"),
            parent.timestamp_ms().saturating_add(1),
            None,
        )
        .expect("construct canonical empty h1 header");
        let block = Block::new(
            header,
            body.application_payload()
                .try_cev0_bytes()
                .expect("encode empty h1 payload"),
            Vec::new(),
        )
        .expect("construct canonical empty h1 block");
        let signing_root =
            ProposalWitnessV0::signing_root_for(block.header(), &justify, None, None)
                .expect("derive empty h1 signing root");
        let mut signature = [0_u8; 64];
        signature[..32].copy_from_slice(signing_root.as_bytes());
        signature[32..].copy_from_slice(signing_root.as_bytes());
        let witness = ProposalWitnessV0::new(
            block.header(),
            justify,
            None,
            None,
            SignatureBytes::from_array(signature),
            set,
            None,
            parameters,
            parent.timestamp_ms(),
        )
        .expect("construct canonical empty h1 witness");
        SignedProposalV0::new(block, witness, set, None, parameters, parent.timestamp_ms())
            .expect("construct canonical empty h1 proposal")
    }

