    fn production_authenticated_genesis_h1_obligation_takeover_fixture_v0(
        label: &str,
    ) -> ProductionAuthenticatedGenesisH1ObligationTakeoverFixtureV0 {
        let (root, application, core_config, prepared, safety_profile, safety_path, genesis) =
            production_authenticated_genesis_commissioning_fixture_v0(label);
        let mut safety = production_authenticated_genesis_safety_v0(
            &safety_path,
            safety_profile.clone(),
            &prepared,
        );
        let tag5 = safety
            .confirmed_authenticated_genesis_application_bootstrap_head_exact_v0(&prepared)
            .expect("confirm production tag-5 head");
        let commissioning_config =
            crate::NativeAuthenticatedGenesisApplicationCommissioningConfigV0::new(
                application.clone(),
            )
            .expect("construct production commissioning config");
        let mut commissioning =
            crate::NativeAuthenticatedGenesisApplicationCommissioningHostV0::open_existing_commissionable_v0(
                commissioning_config,
            )
            .expect("open production commissioning owner");
        let (commissioned, disposition) = commissioning
            .commission_or_confirm_exact_v0(&prepared, &safety, &safety_path, tag5)
            .expect("commission production schema-v14 namespace");
        assert_eq!(
            disposition,
            crate::NativeAuthenticatedGenesisApplicationCommissioningDispositionV0::Commissioned
        );
        drop(commissioned);
        drop(commissioning);

        let fresh_prepared =
            production_authenticated_genesis_prepared_v0(&core_config, genesis.clone());
        let activation = Core::begin_authenticated_genesis_application_h1_offline_validation_v0(
            core_config.clone(),
            fresh_prepared,
            &CoreRootSignatures,
        )
        .expect("begin production h1 owner");
        let mut owner = activation
            .activate_application_v0(TestTakeoverRegistrarV0)
            .expect("activate test-only exact h1 owner");
        let obligation = owner
            .submit_exact_h1_synced_proposal_v0(
                production_authenticated_genesis_empty_h1_v0(&core_config, genesis.clone()),
                &CoreRootSignatures,
            )
            .expect("derive production rev1 obligation");
        let binding = owner
            .issue_safety_persistence_binding_v0()
            .expect("issue production h1 Safety binding");
        let tag5 = safety
            .confirmed_authenticated_genesis_application_bootstrap_head_exact_v0(
                &production_authenticated_genesis_prepared_v0(&core_config, genesis.clone()),
            )
            .expect("refresh production tag-5 head");
        safety
            .bind_authenticated_genesis_application_h1_offline_v0(tag5, binding)
            .expect("bind production h1 Safety owner");
        safety
            .persist_authenticated_genesis_application_h1_obligation_exact_v0(&obligation)
            .expect("persist production rev1 obligation");
        let original_request = owner
            .acknowledge_obligation_persisted_v0(
                &obligation,
                obligation.barrier_v0(),
                &CoreRootSignatures,
            )
            .expect("release original affined request through real StorageAck");

        let app_config = production_authenticated_genesis_h1_takeover_app_config_v0(
            &application,
            &core_config,
            genesis.clone(),
        );
        (
            root,
            application,
            core_config,
            safety_profile,
            safety_path,
            genesis,
            safety,
            owner,
            original_request,
            app_config,
        )
    }

    fn production_authenticated_genesis_h1_takeover_request_v0(
        core_config: &CoreConfig,
        genesis: GenesisQcV0,
        safety: &mut SqliteSafetyStateStoreV0<CoreRootSignatures>,
    ) -> (
        trnm_consensus_core::AuthenticatedGenesisApplicationH1OfflineActivationBundleV0,
        trnm_consensus_core::AuthenticatedGenesisApplicationH1ValidationRequestV0,
    ) {
        let (_revision_zero, revision_one) = safety
            .authenticated_genesis_application_h1_obligation_lineage_readback_v0()
            .expect("read production rev0/rev1 takeover lineage")
            .into_core_states_v0();
        let prepared = production_authenticated_genesis_prepared_v0(core_config, genesis.clone());
        let takeover = Core::begin_authenticated_genesis_application_h1_obligation_takeover_v0(
            core_config.clone(),
            prepared,
            revision_one,
            &CoreRootSignatures,
        )
        .expect("begin production h1 obligation takeover");
        safety
            .activate_and_rebind_authenticated_genesis_application_h1_obligation_takeover_exact_v0(
                takeover,
            )
            .expect("rebind production takeover to the exact live Safety owner")
            .acknowledge_and_release_validation_request_v0(&CoreRootSignatures)
            .expect("release exact takeover request through real StorageAck")
    }

