    #[derive(Debug, PartialEq, Eq)]
    struct NamespaceEntryImageV0 {
        present: bool,
        bytes: Vec<u8>,
        device: u64,
        inode: u64,
        uid: u32,
        gid: u32,
        mode: u32,
        links: u64,
        length: u64,
    }

    fn namespace_entry_image_v0(path: &Path) -> NamespaceEntryImageV0 {
        match path.symlink_metadata() {
            Ok(metadata) => NamespaceEntryImageV0 {
                present: true,
                bytes: fs::read(path).expect("read namespace test entry"),
                device: metadata.dev(),
                inode: metadata.ino(),
                uid: metadata.uid(),
                gid: metadata.gid(),
                mode: metadata.mode(),
                links: metadata.nlink(),
                length: metadata.len(),
            },
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => NamespaceEntryImageV0 {
                present: false,
                bytes: Vec::new(),
                device: 0,
                inode: 0,
                uid: 0,
                gid: 0,
                mode: 0,
                links: 0,
                length: 0,
            },
            Err(error) => panic!("snapshot namespace test entry {}: {error}", path.display()),
        }
    }

    fn authenticated_genesis_namespace_image_v0(
        status_path: &Path,
    ) -> Vec<(String, NamespaceEntryImageV0)> {
        let database = super::application_store_database_path_v0(status_path);
        [
            ("status", status_path.to_path_buf()),
            ("main", database.clone()),
            (
                "wal",
                super::application_store_auxiliary_path_v0(&database, "-wal"),
            ),
            (
                "shm",
                super::application_store_auxiliary_path_v0(&database, "-shm"),
            ),
            (
                "journal",
                super::application_store_auxiliary_path_v0(&database, "-journal"),
            ),
            (
                "lock",
                super::application_store_lock_path_v0(&database)
                    .expect("derive namespace test lock path"),
            ),
        ]
        .into_iter()
        .map(|(name, path)| (name.to_string(), namespace_entry_image_v0(&path)))
        .collect()
    }

