    #[test]
    fn authenticated_genesis_application_production_host_commissions_reopens_and_confirms_exact_v0()
    {
        let (root, application, _core_config, prepared, safety_profile, safety_path, _genesis) =
            production_authenticated_genesis_commissioning_fixture_v0(
                "authenticated-genesis-production-host",
            );
        let status_path = application
            .state_path
            .clone()
            .expect("production commissioning fixture has a status path");
        assert_eq!(
            status_path
                .symlink_metadata()
                .expect("inspect production commissioning status mode")
                .mode()
                & 0o022,
            0,
            "production status cache is writable by group or peers",
        );
        let safety = production_authenticated_genesis_safety_v0(
            &safety_path,
            safety_profile.clone(),
            &prepared,
        );
        let initial_safety = safety
            .confirmed_authenticated_genesis_application_bootstrap_head_exact_v0(&prepared)
            .expect("confirm initial authenticated-genesis Safety head");
        let config = crate::NativeAuthenticatedGenesisApplicationCommissioningConfigV0::new(
            application.clone(),
        )
        .expect("construct production App commissioning config");
        let mut host =
            crate::NativeAuthenticatedGenesisApplicationCommissioningHostV0::open_existing_commissionable_v0(
                config,
            )
            .expect("open production App commissioning owner");
        let (commissioned, disposition) = host
            .commission_or_confirm_exact_v0(&prepared, &safety, &safety_path, initial_safety)
            .expect("commission production schema-v14 application");
        assert_eq!(
            disposition,
            crate::NativeAuthenticatedGenesisApplicationCommissioningDispositionV0::Commissioned
        );
        assert!(commissioned.belongs_to_host_at_path_v0(&host, &status_path));
        let fresh = host
            .fresh_confirm_exact_v0(&prepared, &safety, &safety_path)
            .expect("fresh-confirm production schema-v14 application");
        assert_eq!(fresh.row_checksum_v0(), commissioned.row_checksum_v0());
        let commissioned_image = authenticated_genesis_namespace_image_v0(&status_path);
        drop(host);
        drop(safety);

        let reopened_safety =
            SqliteSafetyStateStoreV0::open_existing_authenticated_genesis_application_exact_v0(
                &safety_path,
                safety_profile,
                CoreRootSignatures,
                &prepared,
            )
            .expect("reopen production authenticated-genesis Safety journal");
        let reopened_safety_head = reopened_safety
            .confirmed_authenticated_genesis_application_bootstrap_head_exact_v0(&prepared)
            .expect("confirm reopened Safety head");
        let config =
            crate::NativeAuthenticatedGenesisApplicationCommissioningConfigV0::new(application)
                .expect("reconstruct production App commissioning config");
        let mut reopened =
            crate::NativeAuthenticatedGenesisApplicationCommissioningHostV0::open_existing_commissionable_v0(
                config,
            )
            .expect("reopen production schema-v14 App owner");
        let (existing, disposition) = reopened
            .commission_or_confirm_exact_v0(
                &prepared,
                &reopened_safety,
                &safety_path,
                reopened_safety_head,
            )
            .expect("confirm exact existing schema-v14 application");
        assert_eq!(
            disposition,
            crate::NativeAuthenticatedGenesisApplicationCommissioningDispositionV0::Existing
        );
        assert!(existing.belongs_to_host_at_path_v0(&reopened, &status_path));
        assert_eq!(existing.row_checksum_v0(), commissioned.row_checksum_v0());
        assert_eq!(
            authenticated_genesis_namespace_image_v0(&status_path),
            commissioned_image,
            "schema-v14 reopen/fresh confirm changed the journal namespace",
        );
        assert_eq!(
            status_path
                .symlink_metadata()
                .expect("reinspect production commissioning status mode")
                .mode()
                & 0o022,
            0,
            "schema-v14 reopen loosened the production status mode",
        );
        drop(reopened);
        drop(reopened_safety);
        fs::remove_dir_all(root).expect("remove production commissioning fixture");
    }

    #[test]
    fn authenticated_genesis_h1_stable_production_c_plus_d_recovers_exactly_to_k_v0() {
        let (root, application, core_config, safety_profile, safety_path, genesis) =
            production_authenticated_genesis_h1_delivered_fixture_v0(
                "authenticated-genesis-h1-stable-c-plus-d",
            );
        let status_path = application
            .state_path
            .clone()
            .expect("stable production fixture has status path");
        let (safety, session, app_config) = production_authenticated_genesis_h1_stable_context_v0(
            &application,
            &core_config,
            safety_profile,
            &safety_path,
            genesis,
        );
        let mut application_host =
            crate::NativeAuthenticatedGenesisH1StableApplicationHostV0::open_existing_v0(
                app_config,
            )
            .expect("open stable production App owner");
        let safety_capability = safety
            .confirmed_authenticated_genesis_application_h1_stable_native_valid_head_exact_v0(
                session.challenge_v0(),
            )
            .expect("confirm stable production Safety capability");
        let mut application_capability = application_host
            .recover_or_confirm_exact_v0(
                session.challenge_v0(),
                &safety,
                &safety_path,
                safety_capability,
            )
            .expect("recover exact production C+D into K");
        assert_eq!(
            application_capability.source_v0(),
            crate::NativeAuthenticatedGenesisH1StableApplicationSourceV0::Delivered
        );
        assert!(application_capability.belongs_to_host_at_path_v0(&application_host, &status_path));
        assert_ne!(
            application_capability.delivered_job_row_checksum_v0(),
            [0; 32]
        );
        assert_ne!(application_capability.acked_job_row_checksum_v0(), [0; 32]);
        assert_ne!(application_capability.outbox_checksum_v0(), [0; 32]);
        assert_ne!(
            application_capability.recovery_closure_checksum_v0(),
            [0; 32]
        );
        let attestation = session
            .challenge_v0()
            .attest_authenticated_reconciliation_v0(
                application_capability.safety_head_facts_v0().clone(),
                &mut application_capability,
            )
            .expect("attest stable App/Safety production join");
        let mut replay = session
            .reconcile_and_complete_v0(attestation)
            .expect("complete stable production Core session");
        let recovered = replay
            .release_inert_completed_facts_v0()
            .expect("release inert stable production facts once");
        assert_eq!(
            recovered.completion_carrier_checksum_v0(),
            application_capability.completion_carrier_checksum_v0()
        );

        drop(recovered);
        drop(replay);
        drop(application_capability);
        drop(application_host);
        drop(safety);
        fs::remove_dir_all(root).expect("remove stable C+D production fixture");
    }

    #[test]
    fn authenticated_genesis_h1_obligation_takeover_absent_cut_is_store_affined_and_inspection_does_not_claim_v0(
    ) {
        let (
            root,
            application,
            core_config,
            _safety_profile,
            _safety_path,
            genesis,
            mut safety,
            original_owner,
            original_request,
            app_config,
        ) = production_authenticated_genesis_h1_obligation_takeover_fixture_v0(
            "authenticated-genesis-h1-obligation-takeover-absent",
        );
        let status_path = application
            .state_path
            .clone()
            .expect("takeover fixture has status path");
        let (activation_bundle, request) = production_authenticated_genesis_h1_takeover_request_v0(
            &core_config,
            genesis,
            &mut safety,
        );
        let host = crate::NativeAuthenticatedGenesisH1ObligationTakeoverHostV0::open_existing_v0(
            app_config,
        )
        .expect("open exact obligation takeover App owner");
        let cut = host
            .inspect_exact_cut_v0(&request)
            .expect("inspect exact Absent App cut");
        assert_eq!(
            cut.source_v0(),
            crate::NativeAuthenticatedGenesisH1ObligationTakeoverSourceV0::Absent
        );
        assert!(cut.belongs_to_host_at_path_v0(&host, &status_path));
        assert_eq!(cut.immutable_checksum_v0(), None);
        assert_eq!(cut.job_row_checksum_v0(), None);
        assert_eq!(cut.artifact_checksum_v0(), None);
        assert_eq!(cut.outbox_checksum_v0(), None);
        assert_eq!(cut.overlay_checksum_v0(), None);
        assert_ne!(cut.accounting_checksum_v0(), [0; 32]);
        assert_ne!(cut.recovery_closure_checksum_v0(), [0; 32]);
        assert_ne!(cut.application_host_config_ref_v0(), [0; 32]);
        assert_ne!(cut.carrier_binding_ref_v0(), [0; 32]);
        assert_ne!(cut.commissioning_row_checksum_v0(), [0; 32]);
        assert_ne!(cut.cut_checksum_v0(), [0; 32]);
        let repeated = host
            .inspect_exact_cut_v0(&request)
            .expect("repeat exact Absent App inspection");
        assert_eq!(repeated.source_v0(), cut.source_v0());
        assert_eq!(
            repeated.accounting_checksum_v0(),
            cut.accounting_checksum_v0()
        );
        assert_eq!(
            repeated.recovery_closure_checksum_v0(),
            cut.recovery_closure_checksum_v0()
        );
        assert_eq!(repeated.cut_checksum_v0(), cut.cut_checksum_v0());
        drop(repeated);
        drop(cut);
        let claimed = request
            .try_claim_v0()
            .expect("fixed-snapshot App inspection did not claim the Core request");

        drop(claimed);
        drop(host);
        drop(original_request);
        drop(original_owner);
        drop(activation_bundle);
        drop(safety);
        fs::remove_dir_all(root).expect("remove takeover Absent fixture");
    }

    #[test]
    fn authenticated_genesis_h1_obligation_takeover_r_p_d_cuts_are_exact_and_typed_v0() {
        std::thread::Builder::new()
            .name("authenticated-genesis-h1-obligation-takeover-r-p-d".to_owned())
            .stack_size(32 * 1024 * 1024)
            .spawn(|| {
                #[derive(Clone, Copy)]
                enum CutShapeV0 {
                    Reserved,
                    CallbackPending,
                    Delivered,
                }

                for (label, shape, expected_source) in [
            (
                "authenticated-genesis-h1-obligation-takeover-reserved",
                CutShapeV0::Reserved,
                crate::NativeAuthenticatedGenesisH1ObligationTakeoverSourceV0::Reserved,
            ),
            (
                "authenticated-genesis-h1-obligation-takeover-callback-pending",
                CutShapeV0::CallbackPending,
                crate::NativeAuthenticatedGenesisH1ObligationTakeoverSourceV0::CallbackPending,
            ),
            (
                "authenticated-genesis-h1-obligation-takeover-delivered",
                CutShapeV0::Delivered,
                crate::NativeAuthenticatedGenesisH1ObligationTakeoverSourceV0::Delivered,
            ),
        ] {
            let (
                root,
                application,
                core_config,
                _safety_profile,
                _safety_path,
                genesis,
                mut safety,
                mut original_owner,
                original_request,
                app_config,
            ) = production_authenticated_genesis_h1_obligation_takeover_fixture_v0(label);
            let status_path = application
                .state_path
                .clone()
                .expect("takeover fixture has status path");
            let host =
                crate::NativeAuthenticatedGenesisH1ObligationTakeoverHostV0::open_existing_v0(
                    app_config,
                )
                .expect("open exact obligation takeover App owner");

            match shape {
                CutShapeV0::Reserved => {
                    host.drive_exact_request_to_reserved_for_test_v0(original_request)
                        .expect("drive exact production request to Reserved");
                    drop(original_owner);
                }
                CutShapeV0::CallbackPending => {
                    host.drive_exact_request_to_callback_pending_for_test_v0(
                        original_request,
                        &original_owner,
                    )
                        .expect("drive exact production request to CallbackPending");
                    drop(original_owner);
                }
                CutShapeV0::Delivered => {
                    host.drive_exact_request_to_delivered_for_test_v0(
                        original_request,
                        &mut original_owner,
                        &safety,
                        &CoreRootSignatures,
                    )
                    .expect("drive exact production request to Delivered");
                    drop(original_owner);
                }
            }

            let (activation_bundle, request) =
                production_authenticated_genesis_h1_takeover_request_v0(
                    &core_config,
                    genesis.clone(),
                    &mut safety,
                );

            let fresh_activation = activation_bundle;
            let fresh_request = request;
            let cut = host
                .inspect_exact_cut_v0(&fresh_request)
                .expect("inspect exact persisted takeover cut");
            assert_eq!(cut.source_v0(), expected_source);
            assert!(cut.belongs_to_host_at_path_v0(&host, &status_path));
            assert!(!cut.belongs_to_host_at_path_v0(&host, &status_path.with_extension("foreign")));
            assert!(cut.immutable_checksum_v0().is_some());
            assert!(cut.job_row_checksum_v0().is_some());
            let accounting_checksum = cut.accounting_checksum_v0();
            let recovery_closure_checksum = cut.recovery_closure_checksum_v0();
            let cut_checksum = cut.cut_checksum_v0();
            match shape {
                CutShapeV0::Reserved => {
                    assert_eq!(cut.artifact_checksum_v0(), None);
                    assert_eq!(cut.outbox_checksum_v0(), None);
                    assert_eq!(cut.overlay_checksum_v0(), None);
                    drop(cut);
                    let claimed = fresh_request
                        .try_claim_v0()
                        .expect("Reserved inspection did not claim the Core request");
                    drop(claimed);
                }
                CutShapeV0::CallbackPending | CutShapeV0::Delivered => {
                    assert!(cut.artifact_checksum_v0().is_some());
                    assert!(cut.outbox_checksum_v0().is_some());
                    assert!(cut.overlay_checksum_v0().is_some());
                    drop(cut);
                    let claimed = fresh_request
                        .try_claim_v0()
                        .expect("P/D inspection did not claim or remint Core request authority");
                    drop(claimed);
                }
            }
            let (repeated_activation, repeated_request) =
                production_authenticated_genesis_h1_takeover_request_v0(
                    &core_config,
                    genesis,
                    &mut safety,
                );
            let repeated = host
                .inspect_exact_cut_v0(&repeated_request)
                .expect("repeat exact persisted takeover cut inspection");
            assert_eq!(repeated.source_v0(), expected_source);
            assert_eq!(repeated.accounting_checksum_v0(), accounting_checksum);
            assert_eq!(
                repeated.recovery_closure_checksum_v0(),
                recovery_closure_checksum
            );
            assert_eq!(repeated.cut_checksum_v0(), cut_checksum);

            drop(repeated);
            drop(repeated_request);
            drop(repeated_activation);
            drop(fresh_activation);
            drop(host);
            drop(safety);
            fs::remove_dir_all(root).expect("remove takeover R/P/D fixture");
        }
            })
            .expect("spawn large-stack takeover R/P/D test")
            .join()
            .expect("join large-stack takeover R/P/D test");
    }

