    #[test]
    fn authenticated_genesis_h1_obligation_takeover_a_r_p_complete_through_single_delivery_attempt_v0(
    ) {
        std::thread::Builder::new()
            .name("authenticated-genesis-h1-obligation-takeover-a-r-p-reexecute".to_owned())
            .stack_size(32 * 1024 * 1024)
            .spawn(|| {
                #[derive(Clone, Copy)]
                enum CutShapeV0 {
                    Absent,
                    Reserved,
                    CallbackPending,
                }

                for (label, shape, expected_source) in [
                    (
                        "authenticated-genesis-h1-obligation-takeover-reexecute-absent",
                        CutShapeV0::Absent,
                        crate::NativeAuthenticatedGenesisH1ObligationTakeoverSourceV0::Absent,
                    ),
                    (
                        "authenticated-genesis-h1-obligation-takeover-reexecute-reserved",
                        CutShapeV0::Reserved,
                        crate::NativeAuthenticatedGenesisH1ObligationTakeoverSourceV0::Reserved,
                    ),
                    (
                        "authenticated-genesis-h1-obligation-takeover-reexecute-pending",
                        CutShapeV0::CallbackPending,
                        crate::NativeAuthenticatedGenesisH1ObligationTakeoverSourceV0::CallbackPending,
                    ),
                ] {
                    let (
                        root,
                        application,
                        core_config,
                        _safety_profile,
                        safety_path,
                        genesis,
                        mut safety,
                        original_owner,
                        original_request,
                        app_config,
                    ) = production_authenticated_genesis_h1_obligation_takeover_fixture_v0(label);
                    let host =
                        crate::NativeAuthenticatedGenesisH1ObligationTakeoverHostV0::open_existing_v0(
                            app_config,
                        )
                        .expect("open exact reexecution App owner");
                    match shape {
                        CutShapeV0::Absent => {
                            drop(original_request);
                            drop(original_owner);
                        }
                        CutShapeV0::Reserved => {
                            host.drive_exact_request_to_reserved_for_test_v0(original_request)
                                .expect("author exact Reserved cut");
                            drop(original_owner);
                        }
                        CutShapeV0::CallbackPending => {
                            host.drive_exact_request_to_callback_pending_for_test_v0(
                                original_request,
                                &original_owner,
                            )
                            .expect("author exact CallbackPending cut");
                            drop(original_owner);
                        }
                    }
                    let (activation, request) =
                        production_authenticated_genesis_h1_takeover_request_v0(
                            &core_config,
                            genesis.clone(),
                            &mut safety,
                        );
                    let cut = host
                        .inspect_exact_cut_v0(&request)
                        .expect("inspect exact reexecution source");
                    assert_eq!(cut.source_v0(), expected_source);
                    let validation_id = cut.validation_id_v0();
                    let status_path = application
                        .state_path
                        .as_deref()
                        .expect("takeover fixture has status path");
                    let completed = host
                        .take_over_and_complete_v0(
                            cut,
                            activation,
                            request,
                            &mut safety,
                            &safety_path,
                            &CoreRootSignatures,
                        )
                        .expect("take over exact A/R/P cut through C/K completion");
                    assert!(completed.belongs_to_host_at_path_v0(status_path));
                    assert_eq!(completed.core_facts_v0().validation_id_v0(), validation_id);
                    assert_eq!(completed.core_facts_v0().safety_revision_v0(), 2);
                    let fresh = completed
                        .fresh_confirm_capability_exact_v0()
                        .expect("freshly confirm completed A/R/P takeover");
                    assert!(fresh.belongs_to_host_at_path_v0(&completed, status_path));
                    assert_eq!(fresh.validation_id_v0(), validation_id);
                    assert_eq!(fresh.application_facts_v0(), completed.application_facts_v0());
                    drop(completed);
                    drop(safety);
                    fs::remove_dir_all(root).expect("remove A/R/P reexecution fixture");
                }
            })
            .expect("spawn large-stack A/R/P reexecution test")
            .join()
            .expect("join large-stack A/R/P reexecution test");
    }

    #[test]
    fn authenticated_genesis_h1_obligation_takeover_delivered_completes_without_second_delivery_attempt_v0(
    ) {
        let (
            root,
            application,
            core_config,
            _safety_profile,
            safety_path,
            genesis,
            mut safety,
            mut original_owner,
            original_request,
            app_config,
        ) = production_authenticated_genesis_h1_obligation_takeover_fixture_v0(
            "authenticated-genesis-h1-obligation-takeover-reexecute-delivered",
        );
        let host = crate::NativeAuthenticatedGenesisH1ObligationTakeoverHostV0::open_existing_v0(
            app_config,
        )
        .expect("open Delivered reexecution App owner");
        host.drive_exact_request_to_delivered_for_test_v0(
            original_request,
            &mut original_owner,
            &safety,
            &CoreRootSignatures,
        )
        .expect("author exact Delivered cut");
        drop(original_owner);
        let (activation, request) = production_authenticated_genesis_h1_takeover_request_v0(
            &core_config,
            genesis.clone(),
            &mut safety,
        );
        let cut = host
            .inspect_exact_cut_v0(&request)
            .expect("inspect exact Delivered cut");
        assert_eq!(
            cut.source_v0(),
            crate::NativeAuthenticatedGenesisH1ObligationTakeoverSourceV0::Delivered
        );
        let status_path = application
            .state_path
            .as_deref()
            .expect("takeover fixture has status path");
        let before = authenticated_genesis_namespace_image_v0(status_path);
        let completed = host
            .take_over_and_complete_v0(
                cut,
                activation,
                request,
                &mut safety,
                &safety_path,
                &CoreRootSignatures,
            )
            .expect("take over exact D attempt one through C/K completion");
        assert!(completed.belongs_to_host_at_path_v0(status_path));
        assert_eq!(completed.core_facts_v0().safety_revision_v0(), 2);
        assert_eq!(
            completed.application_facts_v0().validation_id_v0(),
            completed.core_facts_v0().validation_id_v0()
        );
        let fresh = completed
            .fresh_confirm_capability_exact_v0()
            .expect("freshly confirm retained K owner");
        assert!(fresh.belongs_to_host_at_path_v0(&completed, status_path));
        assert_eq!(fresh.safety_revision_v0(), 2);
        assert_eq!(
            fresh.application_facts_v0(),
            completed.application_facts_v0()
        );
        let database = super::application_store_database_path_v0(status_path);
        let connection = Connection::open_with_flags(
            database,
            OpenFlags::SQLITE_OPEN_READ_ONLY | OpenFlags::SQLITE_OPEN_NO_MUTEX,
        )
        .expect("open completed takeover database read-only");
        let (state, accepted_revision, outbox_count): (i64, Vec<u8>, i64) = connection
            .query_row(
                "SELECT state, accepted_core_revision_be,
                        (SELECT COUNT(*) FROM validation_callback_outbox_v0)
                 FROM validation_jobs_v0",
                [],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
            )
            .expect("read exact completed job and retired outbox");
        assert_eq!(state, 4, "App source is exact Acked K");
        assert_eq!(
            u64::from_be_bytes(accepted_revision.try_into().expect("revision width")),
            2
        );
        assert_eq!(outbox_count, 0, "D attempt one retired without attempt two");
        drop(connection);
        assert_ne!(
            authenticated_genesis_namespace_image_v0(status_path),
            before,
            "only the intended D-to-C-to-K completion mutates the namespace"
        );
        drop(completed);
        drop(safety);
        fs::remove_dir_all(root).expect("remove Delivered reexecution fixture");
    }

